  with Jest invoked successfully and no failures reported in the tool output.

3) Rule implementations providing configurable options, customizable paths, and JSON Schema validation:
- src/rules/valid-story-reference.ts implements configuration for customizable story paths and validation (REQ-CUSTOMIZABLE-PATHS, REQ-RULE-OPTIONS, REQ-CONFIG-VALIDATION):
  """
  const defaultStoryDirs = ["docs/stories", "stories"];
  ...
  meta: {
    type: "problem",
    docs: { ... },
    schema: [
      {
        type: "object",
        properties: {
          storyDirectories: { type: "array", items: { type: "string" } },
          allowAbsolutePaths: { type: "boolean" },
          requireStoryExtension: { type: "boolean" },
        },
        additionalProperties: false,
      },
    ],
  },
  create(context: Rule.RuleContext) {
    const opts = context.options[0] as {
      storyDirectories?: string[];
      allowAbsolutePaths?: boolean;
      requireStoryExtension?: boolean;
    } | undefined;
    const storyDirs = opts?.storyDirectories || defaultStoryDirs;
    const allowAbsolute = opts?.allowAbsolutePaths || false;
    const requireExt = opts?.requireStoryExtension !== false;
    ...
  }
  """
- src/rules/require-story-annotation.ts exposes per-rule configurable options (REQ-RULE-OPTIONS):
  """
  meta: {
    ...,
    schema: [
      {
        type: "object",
        properties: {
          scope: {
            type: "array",
            items: { type: "string", enum: DEFAULT_SCOPE },
            uniqueItems: true,
          },
          exportPriority: { type: "string", enum: EXPORT_PRIORITY_VALUES },
        },
        additionalProperties: false,
      },
    ],
  },
